sp_widget.client_script:
api.controller = function($scope, $timeout) {
  /* Role: everything that happens in the browser: tabs, follow-up lists, search, review buttons, the audit export,
     drag and drop, and the two-step upload (choose files, then Submit). There is no Link function. */
  var c = this;
  $scope.c = c;     /* makes "c" available to the template whatever the "Controller as" setting is */
  c.build = '10';   /* must match the "server build" shown at the bottom of the page */
  console.log('[CPM] widget build ' + c.build + ' loaded');

  var MAX_BYTES = 3 * 1024 * 1024;
  var MAX_FILES = 10;
  var ALLOWED = ['image/png', 'image/jpeg', 'image/gif', 'image/webp', 'application/pdf'];

  /* The follow-up lists. The compliance team sees five of them for the whole company, an owner sees three for their own controls.
     These arrays never change, so the page can loop over them safely. */
  var TEAM_LISTS = [
    { key: 'need', label: 'Missing or rejected' },
    { key: 'expiring', label: 'Expiring soon' },
    { key: 'stale', label: 'Stale (expired)' },
    { key: 'noOwner', label: 'Controls without owner' },
    { key: 'uncovered', label: 'Services without controls' }
  ];
  var MINE_LISTS = [
    { key: 'need', label: 'Need evidence' },
    { key: 'expiring', label: 'Expiring soon' },
    { key: 'stale', label: 'Stale (expired)' }
  ];
  var EMPTY_TEXT = {
    need: 'Nothing is missing or rejected. Well done.',
    expiring: 'Nothing expires soon.',
    stale: 'Nothing is stale.',
    noOwner: 'Every control has an owner.',
    uncovered: 'Every service has at least one control.'
  };

  /* Block 1: labels and state of the screen. */
  c.label = {
    approved: 'Approved', expiring: 'Expiring soon', awaiting: 'Awaiting review',
    rejected: 'Rejected', missing: 'Needs evidence', expired: 'Expired', uncovered: 'Not covered'
  };
  c.riskLabel = { green: 'On track', yellow: 'Watch', red: 'Action needed', not_assessed: 'Not assessed' };
  c.tab = ($scope.data && $scope.data.isAdmin) ? 'review' : 'mine';   /* owners only have "my services" */
  c.sel = { team: 'need', mine: 'need' };                              /* the list selected in each follow-up block */
  c.q = '';          /* the text typed in the search bar */
  c.filter = 'all';  /* the risk chip that is selected */
  c.filters = [
    { key: 'all', label: 'All' }, { key: 'red', label: 'Action needed' }, { key: 'yellow', label: 'Watch' },
    { key: 'green', label: 'On track' }, { key: 'not_assessed', label: 'Not assessed' }
  ];
  c.staged = {};     /* files chosen but not yet submitted, per control */
  c.busy = {};       /* upload in progress, per control */
  c.progress = {};   /* text of the Submit button while sending, per control */
  c.msg = {};        /* error shown under the upload area, per control */
  c.working = {};    /* review action in progress, per submission */
  c.rejecting = {};  /* reject box open, per submission */
  c.comment = {};    /* rejection reason typed, per submission */
  c.opening = '';    /* id of the file being opened */
  c.preview = null;  /* image shown in the viewer */
  c.exporting = false;
  c.toast = null;    /* last result, shown at the top of the page */

  /* Block 2: talking to the server.
     server.get() returns the server's answer WITHOUT updating the page data, so the answer is read here.
     ask()     sends a request and returns the answer (the page data is left alone: used for light requests);
     refresh() does the same, then replaces the page data with the answer (used after an action). */
  function dataOf(response) {
    var d = response && response.data;
    return (d && typeof d === 'object' && d.serverBuild !== undefined) ? d : null;
  }
  function ask(extra) {
    var payload = angular.extend({}, ($scope.data || {}).params, extra || {});
    return c.server.get(payload).then(dataOf);
  }
  function refresh(extra) {
    return ask(extra).then(function(fresh) {
      if (fresh) $scope.data = fresh;
      return fresh;
    });
  }

  /* Keeps &debug=1 on every link when it is switched on. */
  c.dbg = function() {
    return (($scope.data || {}).params || {}).debug == '1' ? '&debug=1' : '';
  };

  /* Block 3: the banner: a sentence that tells where the person stands, a tick at the goal on the ring, and the coverage. */
  c.hero = function() {
    var d = $scope.data || {};
    var part = d.isAdmin ? d.team : d.mine;
    return (part && part.kpi) || { coverage: 0 };
  };
  c.tick = function() {
    var goal = Math.max(1, Math.min(99, ($scope.data || {}).goal || 80));
    var angle = goal / 100 * 2 * Math.PI - Math.PI / 2;
    function point(radius, axis) { return 32 + radius * (axis === 'x' ? Math.cos(angle) : Math.sin(angle)); }
    return { x1: point(21, 'x'), y1: point(21, 'y'), x2: point(32, 'x'), y2: point(32, 'y') };
  };
  c.headline = function() {
    var d = $scope.data || {};
    var kpi = c.hero();
    var goal = d.goal || 80;
    if (d.isAdmin) {
      var waiting = (d.team && d.team.kpi) ? d.team.kpi.review : 0;
      if (waiting) return waiting + ' submission' + (waiting === 1 ? ' is' : 's are') + ' waiting for your review.';
      return kpi.coverage >= goal
        ? 'The company is on track: ' + kpi.coverage + '% of controls are approved.'
        : 'Coverage is ' + kpi.coverage + '%, below the ' + goal + '% goal. The follow-up lists show where to act.';
    }
    var follow = d.myFollow || {};
    var todo = (follow.need ? follow.need.count : 0) + (follow.stale ? follow.stale.count : 0);
    var soon = follow.expiring ? follow.expiring.count : 0;
    if (!d.mine || !d.mine.kpi || !d.mine.kpi.targets) return 'Nothing is assigned to you yet.';
    if (todo) return 'You have ' + todo + ' control' + (todo === 1 ? '' : 's') + ' to complete. One at a time is enough.';
    if (soon) return 'Everything is approved. ' + soon + ' will need a renewal soon.';
    return 'All clear: every control you own is approved.';
  };

  /* "Start here": the most useful single next step for the person, computed once per page load. */
  var nextCache = { data: null, value: null };
  function computeNext(d) {
    var follow = (d && d.myFollow) || {};
    var need = (follow.need && follow.need.items) || [];
    var stale = (follow.stale && follow.stale.items) || [];
    var soon = (follow.expiring && follow.expiring.items) || [];
    var rejected = need.filter(function(r) { return r.status === 'rejected'; });
    var missing = need.filter(function(r) { return r.status !== 'rejected'; });
    if (rejected.length) return { item: rejected[0], why: 'A reviewer asked for a better proof' };
    if (stale.length) return { item: stale[0], why: 'The previous proof has expired: renew it' };
    if (missing.length) return { item: missing[0], why: 'No evidence yet' };
    if (soon.length) return { item: soon[0], why: 'Expires in ' + soon[0].daysLeft + ' day' + (soon[0].daysLeft === 1 ? '' : 's') };
    return null;
  }
  c.nextAction = function() {
    var d = $scope.data;
    if (nextCache.data !== d) { nextCache.data = d; nextCache.value = computeNext(d); }
    return nextCache.value;
  };

  /* Block 4: tabs, headline tiles and follow-up lists. */

  /* Opens a tab, and optionally selects the list to show in it. The headline tiles use this. */
  c.go = function(tab, listKey) {
    c.tab = tab;
    if (listKey) c.sel[tab === 'follow' ? 'team' : 'mine'] = listKey;
  };
  /* Which block of lists is shown: the company's (tab Follow-up) or my own (tab My services). */
  c.ctx = function() { return c.tab === 'follow' ? 'team' : 'mine'; };
  c.showFollow = function() { return c.tab === 'follow' || c.tab === 'mine'; };
  c.showCards = function() { return c.tab === 'all' || c.tab === 'mine'; };
  c.defs = function() { return c.ctx() === 'team' ? TEAM_LISTS : MINE_LISTS; };
  c.section = function() { return c.sel[c.ctx()]; };
  c.pick = function(key) { c.sel[c.ctx()] = key; };
  function followSet() {
    var d = $scope.data || {};
    return (c.ctx() === 'team' ? d.follow : d.myFollow) || {};
  }
  c.countOf = function(key) {
    var part = followSet()[key];
    return part ? part.count : 0;
  };
  c.items = function() {
    var part = followSet()[c.section()];
    return part ? part.items : [];
  };
  c.more = function() {
    var part = followSet()[c.section()];
    return part ? Math.max(0, part.count - part.items.length) : 0;
  };
  c.emptyText = function() { return EMPTY_TEXT[c.section()] || 'Nothing to show.'; };

  /* Chooses, for each block, the first list that has something in it. It runs once, when the page opens. */
  (function pickFirstFilled() {
    var d = $scope.data || {};
    [['team', d.follow, TEAM_LISTS], ['mine', d.myFollow, MINE_LISTS]].forEach(function(entry) {
      var set = entry[1] || {};
      for (var i = 0; i < entry[2].length; i++) {
        var key = entry[2][i].key;
        if (set[key] && set[key].count) { c.sel[entry[0]] = key; return; }
      }
    });
  })();

  /* Block 5: the service cards, the search bar and the risk chips. Everything is filtered in the browser, so it is instant. */
  function cardPart() {
    var d = $scope.data || {};
    return (c.tab === 'all' && d.team) ? d.team : d.mine;
  }
  c.rows = function() {
    var part = cardPart();
    return (part && part.rows) || [];
  };
  c.limited = function() {
    var part = cardPart();
    return !!(part && part.truncated);
  };
  function matchesText(row) {
    var q = (c.q || '').trim().toLowerCase();
    return !q || ((row.name || '') + ' ' + (row.kind || '')).toLowerCase().indexOf(q) > -1;
  }
  c.match = function(row) {
    return matchesText(row) && (c.filter === 'all' || row.risk === c.filter);
  };
  c.count = function(key) {
    return c.rows().filter(function(r) { return matchesText(r) && (key === 'all' || r.risk === key); }).length;
  };

  /* Block 6: the compliance team's decisions. The server does the work, emails the owner, and the page is refreshed. */
  function review(evidence, payload) {
    c.working[evidence.id] = true;
    var done = function() { c.working[evidence.id] = false; };
    refresh(payload).then(done, done);
  }
  c.approve = function(evidence) {
    review(evidence, { action: 'approve', evidence: evidence.id });
  };
  c.reject = function(evidence) {
    review(evidence, { action: 'reject', evidence: evidence.id, comment: c.comment[evidence.id] });
  };

  /* Block 7: opening a submitted file. Images appear in the viewer, other files are downloaded. */
  function downloadLink(href, name) {
    var link = document.createElement('a');
    link.href = href;
    link.download = name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
  c.open = function(evidenceId, file) {
    c.opening = file.id;
    ask({ action: 'file', evidence: evidenceId, attachment: file.id }).then(function(fresh) {
      c.opening = '';
      var result = fresh && fresh.file;
      if (!result || !result.ok) {
        c.toast = { type: 'error', text: (result && result.message) || 'The file could not be opened.' };
        return;
      }
      var href = 'data:' + result.type + ';base64,' + result.content;
      if (/^image\//.test(result.type)) c.preview = { name: result.name, src: href };
      else downloadLink(href, result.name);
    }, function() {
      c.opening = '';
      c.toast = { type: 'error', text: 'The file could not be opened.' };
    });
  };

  /* Block 8: the audit export. The server returns the approved proofs, and the browser builds a CSV file from them. */
  function csvCell(value) {
    var text = String(value === null || value === undefined ? '' : value);
    if (/^[=+\-@]/.test(text)) text = "'" + text;   /* stops a spreadsheet from running a cell as a formula */
    return '"' + text.replace(/"/g, '""') + '"';
  }
  c.exportAudit = function() {
    c.exporting = true;
    ask({ action: 'audit' }).then(function(fresh) {
      c.exporting = false;
      var rows = fresh && fresh.audit;
      if (!rows) { c.toast = { type: 'error', text: 'The audit export could not be prepared.' }; return; }
      var head = ['Evidence', 'Service or CI', 'Control reference', 'Control', 'Framework', 'Status', 'Submitted by', 'Submitted on',
                  'Reviewed by', 'Reviewed on', 'Valid until', 'Scope at approval', 'Files', 'Integrity'];
      var lines = [head.map(csvCell).join(',')];
      rows.forEach(function(r) {
        lines.push([r.number, r.target, r.ref, r.control, r.framework, r.status, r.submittedBy, r.submittedOn,
                    r.reviewedBy, r.reviewedOn, r.validUntil, r.scope, r.files, r.integrity].map(csvCell).join(','));
      });
      var blob = new Blob(['\ufeff' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8;' });
      var url = URL.createObjectURL(blob);
      downloadLink(url, 'compliance-audit-' + new Date().toISOString().substring(0, 10) + '.csv');
      $timeout(function() { URL.revokeObjectURL(url); }, 2000);
      c.toast = { type: 'ok', text: rows.length + ' approved proof' + (rows.length === 1 ? '' : 's') + ' exported.' };
    }, function() {
      c.exporting = false;
      c.toast = { type: 'error', text: 'The audit export failed.' };
    });
  };

  /* Block 9, step 1 of an upload: choosing files. Nothing is sent to the server here. */

  /* Gives pasted screenshots a readable name, because browsers call them "image.png". */
  function fileName(file) {
    var plain = file.name && file.name !== 'image.png';
    return plain ? file.name : 'screenshot-' + Date.now() + '-' + Math.floor(Math.random() * 1000) + '.png';
  }
  function humanSize(bytes) {
    return bytes > 1024 * 1024 ? (bytes / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round(bytes / 1024)) + ' KB';
  }
  /* Returns a sentence when a file cannot be accepted, or '' when it is fine. */
  function problemWith(file, list) {
    if (ALLOWED.indexOf(file.type) < 0) return 'Only images (PNG, JPG, GIF, WEBP) and PDF files are accepted.';
    if (file.size > MAX_BYTES) return 'This file is larger than 3 MB. Take a smaller screenshot, or save it as a JPG or PDF.';
    if (list.length >= MAX_FILES) return 'A submission can hold up to ' + MAX_FILES + ' files.';
    return '';
  }

  /* Receives the files the user dropped, pasted or chose, and shows them as previews. */
  c.stage = function(mappingId, files) {
    console.log('[CPM] ' + files.length + ' file(s) chosen for control ' + mappingId);
    var list = c.staged[mappingId] = c.staged[mappingId] || [];
    c.msg[mappingId] = '';
    c.toast = null;
    files.forEach(function(file) {
      var problem = problemWith(file, list);
      if (problem) { c.msg[mappingId] = problem; return; }
      var reader = new FileReader();
      reader.onload = function() {
        $timeout(function() {
          list.push({
            name: fileName(file), type: file.type, size: humanSize(file.size),
            isImage: /^image\//.test(file.type), dataUrl: reader.result,
            content: String(reader.result).split(',')[1] || ''
          });
        });
      };
      reader.onerror = function() { $timeout(function() { c.msg[mappingId] = 'This file could not be read.'; }); };
      reader.readAsDataURL(file);
    });
  };
  c.unstage = function(mappingId, index) {
    (c.staged[mappingId] || []).splice(index, 1);
  };
  c.clearStaged = function(mappingId) {
    c.staged[mappingId] = [];
    c.msg[mappingId] = '';
  };

  /* Block 9, step 2 of an upload: the Submit button. The files go one after another into a private draft on the
     server, then the draft is submitted, and only then the compliance team is told. */
  function fail(mappingId, text) {
    c.busy[mappingId] = false;
    c.msg[mappingId] = text;
    c.toast = { type: 'error', text: text };
  }
  function checkAnswer(mappingId, fresh) {
    if (!fresh) { fail(mappingId, 'The server did not answer. Look for "[CPM]" lines in System Log > All, and check that every Script Include is saved.'); return false; }
    if (fresh.error) { fail(mappingId, fresh.error); return false; }
    if (!fresh.upload) { fail(mappingId, 'The server did not confirm the request. The widget Server script may be out of date.'); return false; }
    if (!fresh.upload.ok) { fail(mappingId, fresh.upload.message); return false; }
    return true;
  }
  function sendFile(mappingId, list, index) {
    if (index >= list.length) return submit(mappingId);
    c.progress[mappingId] = 'Sending file ' + (index + 1) + ' of ' + list.length + '…';
    var file = list[index];
    ask({ action: 'addFile', mapping: mappingId, fileName: file.name, contentType: file.type, content: file.content, first: index === 0 })
      .then(function(fresh) {
        if (checkAnswer(mappingId, fresh)) sendFile(mappingId, list, index + 1);
      }, function() {
        fail(mappingId, 'The request failed. Check your connection, or that the files are smaller than 3 MB.');
      });
  }
  function submit(mappingId) {
    c.progress[mappingId] = 'Submitting…';
    refresh({ action: 'submit', mapping: mappingId }).then(function(fresh) {
      if (!checkAnswer(mappingId, fresh)) return;
      c.busy[mappingId] = false;
      c.staged[mappingId] = [];
      c.toast = { type: 'ok', text: 'Submitted. The compliance team will approve or reject your evidence.' };
    }, function() {
      fail(mappingId, 'The request failed. Please try again.');
    });
  }
  c.submit = function(ctl) {
    var list = c.staged[ctl.id] || [];
    if (!list.length || c.busy[ctl.id]) return;
    c.msg[ctl.id] = '';
    c.toast = null;
    c.busy[ctl.id] = true;
    sendFile(ctl.id, list, 0);
  };

  /* Block 10: drag and drop, file picker and paste. The listeners sit on the document and only react to events that
     happen inside a drop zone. They are removed when the widget is destroyed. */
  function hasFiles(e) {
    var types = (e.dataTransfer && e.dataTransfer.types) || [];
    return Array.prototype.indexOf.call(types, 'Files') > -1;
  }
  function zoneOf(e) {
    return e.target && e.target.closest ? e.target.closest('.cpm-drop') : null;
  }
  /* The id of the control a drop zone belongs to (it is written on the hidden file input inside the zone). */
  function mappingOf(zone) {
    var input = zone.querySelector('.cpm-picker');
    return input ? input.getAttribute('data-mapping') : '';
  }
  function choose(mappingId, fileList) {
    var files = Array.prototype.slice.call(fileList);
    $scope.$apply(function() { c.stage(mappingId, files); });
  }
  function onDrag(e) {
    if (!hasFiles(e) || !document.querySelector('.cpm')) return;
    var zone = zoneOf(e);
    e.preventDefault();   /* also stops the browser from opening a file dropped outside a zone */
    if (e.dataTransfer) e.dataTransfer.dropEffect = zone ? 'copy' : 'none';
    if (zone) zone.classList.add('over');
  }
  function onLeave(e) {
    var zone = zoneOf(e);
    if (zone) zone.classList.remove('over');
  }
  function onDrop(e) {
    if (!hasFiles(e) || !document.querySelector('.cpm')) return;
    e.preventDefault();
    var zone = zoneOf(e);
    if (!zone) return;
    zone.classList.remove('over');
    choose(mappingOf(zone), e.dataTransfer.files);
  }
  function onChange(e) {
    if (!e.target.classList || !e.target.classList.contains('cpm-picker')) return;
    var mappingId = e.target.getAttribute('data-mapping');
    var files = Array.prototype.slice.call(e.target.files);
    e.target.value = '';
    $scope.$apply(function() { c.stage(mappingId, files); });
  }
  function onPaste(e) {
    if (!e.clipboardData || !e.clipboardData.files.length) return;
    var zone = document.querySelector('.cpm .cpm-ctl:hover .cpm-drop');
    if (!zone) return;
    e.preventDefault();
    choose(mappingOf(zone), e.clipboardData.files);
  }
  document.addEventListener('dragenter', onDrag);
  document.addEventListener('dragover', onDrag);
  document.addEventListener('dragleave', onLeave);
  document.addEventListener('drop', onDrop);
  document.addEventListener('change', onChange);
  document.addEventListener('paste', onPaste);
  $scope.$on('$destroy', function() {
    document.removeEventListener('dragenter', onDrag);
    document.removeEventListener('dragover', onDrag);
    document.removeEventListener('dragleave', onLeave);
    document.removeEventListener('drop', onDrop);
    document.removeEventListener('change', onChange);
    document.removeEventListener('paste', onPaste);
  });
};

sp_widget.css:
/* Role: the palette. Each colour carries a meaning, and they are used the same way everywhere:
   navy = trust and authority, teal = safe and done, amber = watch the date, coral = act now (used sparingly,
   with soft tinted backgrounds, so people are not worn out by alarms), calm blue = someone is on it, slate = not started. */
.cpm {
  --ink: #0f1b2d; --muted: #5b6b82; --bg: #f4f7fb; --card: #ffffff; --line: #e3e9f2;
  --brand: #17408b; --brand-dark: #0b2a5b;
  --ok: #0f9d75;     --ok-soft: #e5f6f0;     --ok-ink: #0a6b50;
  --watch: #e8a317;  --watch-soft: #fdf3dc;  --watch-ink: #8a5a00;
  --action: #df5a49; --action-soft: #fdecea; --action-ink: #9b2c20;
  --review: #3b6fd4; --review-soft: #e8effc; --review-ink: #234aa0;
  --idle: #8a97ab;   --idle-soft: #eef1f6;   --idle-ink: #4c5b72;
  color: var(--ink);
  background: var(--bg);
  padding: 22px;
  border-radius: 24px;
}
.cpm * { box-sizing: border-box; }
.cpm a { color: inherit; }
.cpm a:hover { text-decoration: none; }

/* Role: messages at the top of the page. */
.cpm-alert { background: var(--action-soft); color: var(--action-ink); padding: 14px 18px; border-radius: 14px; margin-bottom: 14px; }
.cpm-notice, .cpm-toast { padding: 12px 18px; border-radius: 14px; margin-bottom: 14px; font-size: 14px; }
.cpm-notice.ok, .cpm-toast.ok { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-notice.error, .cpm-toast.error { background: var(--action-soft); color: var(--action-ink); }
.cpm-toast a { float: right; font-weight: 700; margin-left: 12px; }
.cpm-version { font-size: 11px; color: var(--muted); text-align: right; margin-top: 24px; }

/* Role: the banner. Deep blue for trust, a touch of teal for progress. */
.cpm-hero { display: flex; justify-content: space-between; align-items: center; gap: 20px; padding: 28px 32px; margin-bottom: 18px;
  border-radius: 22px; color: #fff; box-shadow: 0 14px 34px rgba(11,42,91,.22);
  background: linear-gradient(135deg, #0b2a5b 0%, #17408b 55%, #0f7c8a 100%); }
.cpm-hero h2 { margin: 4px 0 6px; font-size: 28px; color: #fff; }
.cpm-headline { margin: 0 0 10px; font-size: 16px; opacity: .95; max-width: 560px; }
.cpm-goal { display: inline-block; font-size: 12px; padding: 3px 12px; border-radius: 999px; background: rgba(255,255,255,.16); }
.cpm-eyebrow { font-size: 11px; letter-spacing: .12em; text-transform: uppercase; opacity: .75; }
.cpm-eyebrow.dark { color: var(--brand); opacity: 1; }
.cpm-hero-ring { position: relative; width: 104px; height: 104px; flex: none; }
.cpm-hero-ring svg { width: 100%; height: 100%; overflow: visible; }
.cpm-hero-label { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.cpm-hero-label b { font-size: 24px; line-height: 1; }
.cpm-hero-label span { font-size: 10px; opacity: .75; }
.cpm-hero .track { fill: none; stroke: rgba(255,255,255,.2); stroke-width: 7; }
.cpm-hero .bar { fill: none; stroke: #5eead4; stroke-width: 7; stroke-linecap: round; }
.cpm-hero .goal-tick { stroke: #fff; stroke-width: 1.6; stroke-linecap: round; opacity: .9; }

/* Role: the headline numbers. The coloured edge and the icon say what a tile means before it is read. */
.cpm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 14px; margin-bottom: 20px; }
.cpm-kpi { position: relative; background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 16px 16px 14px 18px; box-shadow: 0 2px 8px rgba(15,27,45,.04); }
.cpm-kpi::before { content: ''; position: absolute; left: 0; top: 14px; bottom: 14px; width: 4px; border-radius: 0 4px 4px 0; background: var(--brand); }
.cpm-kpi i { font-style: normal; position: absolute; right: 14px; top: 12px; font-size: 16px; opacity: .55; }
.cpm-kpi b { display: block; font-size: 30px; line-height: 1.1; }
.cpm-kpi span { font-size: 12px; color: var(--muted); }
.cpm-kpi.ok::before { background: var(--ok); }       .cpm-kpi.ok i { color: var(--ok); }
.cpm-kpi.watch::before { background: var(--watch); } .cpm-kpi.watch i { color: var(--watch); }
.cpm-kpi.action::before { background: var(--action); } .cpm-kpi.action i { color: var(--action); }
.cpm-kpi.review::before { background: var(--review); } .cpm-kpi.review i { color: var(--review); }
.cpm-kpi.idle::before { background: var(--idle); }   .cpm-kpi.idle i { color: var(--idle); }
.cpm-kpi.clickable { cursor: pointer; transition: transform .15s, box-shadow .15s; }
.cpm-kpi.clickable:hover { transform: translateY(-2px); box-shadow: 0 10px 24px rgba(15,27,45,.1); }

/* Role: the tabs of the compliance team, with the export button on the right. */
.cpm-tabs { display: flex; gap: 6px; margin: 4px 0 16px; border-bottom: 1px solid var(--line); flex-wrap: wrap; align-items: center; }
.cpm-tabs button { border: 0; background: transparent; padding: 10px 16px; font-weight: 600; color: var(--muted); border-bottom: 3px solid transparent; cursor: pointer; }
.cpm-tabs button.active { color: var(--brand); border-bottom-color: var(--brand); }
.cpm-tabs button.cpm-export { margin-left: auto; border: 1px solid var(--line); border-radius: 10px; background: var(--card); color: var(--brand); padding: 7px 14px; font-size: 13px; }
.cpm-count { display: inline-block; min-width: 22px; text-align: center; background: var(--review); color: #fff; border-radius: 999px; font-size: 11px; padding: 1px 7px; margin-left: 4px; }

/* Role: empty states. "good" ones celebrate: an empty list is a success. */
.cpm-empty { text-align: center; color: var(--muted); padding: 28px; background: var(--card); border: 1px dashed var(--line); border-radius: 16px; margin-bottom: 14px; }
.cpm-empty.good { background: var(--ok-soft); border-color: transparent; color: var(--ok-ink); font-weight: 600; }

/* Role: "Start here": the single most useful next step, to avoid the paralysis of a long list. */
.cpm-next { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 18px 22px; margin-bottom: 16px;
  border-radius: 18px; background: linear-gradient(135deg, #eef3ff, #e5f6f0); border: 1px solid #d5e2f7; }
.cpm-next h4 { margin: 2px 0 2px; font-size: 17px; }
.cpm-next p { margin: 0; color: var(--muted); font-size: 13px; }

/* Role: the review inbox cards and every button of the portal. */
.cpm-review { background: var(--card); border: 1px solid var(--line); border-left: 4px solid var(--review); border-radius: 18px; padding: 16px 20px; margin-bottom: 12px; box-shadow: 0 2px 8px rgba(15,27,45,.04); }
.cpm-review-top { display: flex; justify-content: space-between; gap: 12px; }
.cpm-review-title { font-weight: 600; font-size: 16px; }
.cpm-age { font-size: 12px; padding: 3px 10px; border-radius: 999px; background: var(--idle-soft); color: var(--idle-ink); align-self: flex-start; white-space: nowrap; }
.cpm-age.late { background: var(--action-soft); color: var(--action-ink); }
.cpm-actions { display: flex; gap: 10px; margin-top: 12px; }
.cpm-btn { border: 0; border-radius: 12px; padding: 9px 20px; font-weight: 600; color: #fff; cursor: pointer; text-decoration: none; display: inline-block; }
.cpm-btn.ok { background: var(--ok); } .cpm-btn.bad { background: var(--action); } .cpm-btn.brand { background: var(--brand); }
.cpm-btn.plain { background: var(--idle-soft); color: var(--ink); }
.cpm-btn[disabled] { opacity: .5; cursor: default; }
.cpm-rejectbox { margin-top: 10px; }
.cpm-rejectbox textarea { width: 100%; border: 1px solid #cbd5e1; border-radius: 12px; padding: 8px 12px; margin-bottom: 8px; }

/* Role: panels (follow-up lists, composition, framework coverage). */
.cpm-panel { background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: 18px 22px; margin-bottom: 16px; box-shadow: 0 2px 8px rgba(15,27,45,.04); }
.cpm-panel h4 { margin: 0 0 12px; font-size: 15px; }
.cpm-fw { margin-bottom: 10px; }
.cpm-fw-line { display: flex; justify-content: space-between; font-size: 13px; margin-bottom: 4px; }
.cpm-rollup { background: var(--bg); border-radius: 12px; padding: 10px 14px; font-size: 13px; margin: 8px 0 12px; }

/* Role: tables of the follow-up lists and of the service composition. */
.cpm-tablewrap { overflow-x: auto; margin-top: 8px; }
.cpm-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.cpm-table th { text-align: left; font-size: 12px; color: var(--muted); font-weight: 600; padding: 8px 10px; border-bottom: 1px solid var(--line); white-space: nowrap; }
.cpm-table td { padding: 10px; border-bottom: 1px solid #f1f5f9; vertical-align: top; }
.cpm-table tr:hover td { background: #f8fafc; }
.cpm-table a { color: var(--brand); font-weight: 600; }
.cpm-mini { min-width: 160px; }
.cpm-mini small { color: var(--muted); font-size: 11px; }
.cpm-status { font-size: 12px; font-weight: 600; padding: 2px 10px; border-radius: 999px; background: var(--idle-soft); color: var(--idle-ink); white-space: nowrap; }
.cpm-status.st-missing, .cpm-status.st-rejected, .cpm-status.st-expired, .cpm-status.st-uncovered { background: var(--action-soft); color: var(--action-ink); }
.cpm-status.st-approved { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-status.st-expiring { background: var(--watch-soft); color: var(--watch-ink); }
.cpm-status.st-awaiting { background: var(--review-soft); color: var(--review-ink); }
.cpm-flag { display: inline-block; font-size: 12px; font-weight: 700; padding: 2px 10px; border-radius: 999px; background: var(--watch-soft); color: var(--watch-ink); white-space: nowrap; }

/* Role: filter chips and search bar. */
.cpm-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 10px; }
.cpm-chips { margin-bottom: 6px; }
.cpm-chips button { border: 1px solid #cbd5e1; background: var(--card); border-radius: 999px; padding: 6px 14px; margin: 0 6px 6px 0; font-size: 13px; cursor: pointer; }
.cpm-chips button.active { background: var(--brand); border-color: var(--brand); color: #fff; }
.cpm-searchbar { display: flex; gap: 8px; align-items: center; }
.cpm-search { border: 1px solid #cbd5e1; border-radius: 12px; padding: 9px 14px; min-width: 280px; background: #fff; }
.cpm-search:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px rgba(23,64,139,.15); }

/* Role: the service cards. The ring colour is the risk, and the wording is encouraging: On track, Watch, Action needed. */
.cpm-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 16px; margin: 12px 0 22px; }
.cpm-card { display: block; background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: 18px; box-shadow: 0 2px 8px rgba(15,27,45,.04); transition: transform .15s, box-shadow .15s; }
.cpm-card:hover { transform: translateY(-3px); box-shadow: 0 14px 30px rgba(15,27,45,.12); }
.cpm-card-head { display: flex; align-items: center; gap: 14px; margin-bottom: 14px; }
.cpm-card-title { font-weight: 600; font-size: 16px; margin-bottom: 4px; }
.cpm-card-foot { display: flex; justify-content: space-between; font-size: 12px; color: var(--muted); margin-top: 10px; }
.cpm-kind { color: var(--muted); font-size: 11px; margin-left: 6px; }

/* Role: the progress rings, drawn with SVG and coloured by risk. */
.cpm-ring { width: 64px; height: 64px; flex: none; }
.cpm-ring.big { width: 84px; height: 84px; }
.cpm-ring .track { fill: none; stroke: var(--line); stroke-width: 7; }
.cpm-ring .bar { fill: none; stroke-width: 7; stroke-linecap: round; }
.cpm-ring text { font-size: 15px; font-weight: 700; fill: var(--ink); }
.risk-green .bar { stroke: var(--ok); } .risk-yellow .bar { stroke: var(--watch); }
.risk-red .bar { stroke: var(--action); } .risk-not_assessed .bar { stroke: var(--idle); }
.cpm-pill { font-size: 11px; font-weight: 600; padding: 2px 10px; border-radius: 999px; background: var(--idle-soft); color: var(--idle-ink); }
.cpm-pill.r-green { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-pill.r-yellow { background: var(--watch-soft); color: var(--watch-ink); }
.cpm-pill.r-red { background: var(--action-soft); color: var(--action-ink); }

/* Role: the split bar: approved / expiring / in review / rejected / missing at a glance. */
.cpm-seg { display: flex; height: 8px; border-radius: 999px; overflow: hidden; background: var(--line); }
.cpm-seg i { display: block; flex: 0 1 0; }
.cpm-seg .ok { background: var(--ok); } .cpm-seg .watch { background: var(--watch); } .cpm-seg .review { background: var(--review); }
.cpm-seg .action { background: var(--action); } .cpm-seg .idle { background: var(--idle); }

/* Role: header and control cards of the page of one CI or service. */
.cpm-back { font-size: 13px; color: var(--muted); }
.cpm-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; background: var(--card); border: 1px solid var(--line);
  border-radius: 22px; padding: 20px 24px; margin: 10px 0 16px; box-shadow: 0 2px 8px rgba(15,27,45,.04); }
.cpm-head-main { flex: 1; min-width: 220px; }
.cpm-head h3 { margin: 0 0 2px; }
.cpm-sub { font-size: 12px; color: var(--muted); margin-bottom: 8px; }
.cpm-partof { font-size: 12px; margin-bottom: 8px; }
.cpm-partof a { color: var(--brand); font-weight: 600; }
.cpm-head-stats { display: flex; gap: 22px; text-align: center; }
.cpm-head-stats b { display: block; font-size: 22px; line-height: 1.1; }
.cpm-head-stats span { font-size: 11px; color: var(--muted); }
.cpm-ctl { background: var(--card); border: 1px solid var(--line); border-left: 4px solid var(--idle); border-radius: 18px; padding: 16px 20px; margin-bottom: 12px; box-shadow: 0 2px 8px rgba(15,27,45,.04); }
.cpm-ctl.st-approved { border-left-color: var(--ok); } .cpm-ctl.st-expiring { border-left-color: var(--watch); }
.cpm-ctl.st-awaiting { border-left-color: var(--review); }
.cpm-ctl.st-rejected, .cpm-ctl.st-expired { border-left-color: var(--action); }
.cpm-ctl-top { display: flex; justify-content: space-between; gap: 12px; }
.cpm-state { font-size: 12px; font-weight: 600; white-space: nowrap; padding: 3px 12px; border-radius: 999px; height: fit-content; background: var(--idle-soft); color: var(--idle-ink); }
.cpm-state.st-approved { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-state.st-expiring { background: var(--watch-soft); color: var(--watch-ink); }
.cpm-state.st-awaiting { background: var(--review-soft); color: var(--review-ink); }
.cpm-state.st-rejected, .cpm-state.st-expired { background: var(--action-soft); color: var(--action-ink); }
.cpm-text { font-size: 13px; margin: 8px 0 4px; }
.cpm-guide { font-size: 13px; color: var(--muted); margin: 6px 0; }
.cpm-reject { background: var(--action-soft); color: var(--action-ink); border-radius: 12px; padding: 10px 14px; font-size: 13px; margin: 8px 0; }
.cpm-wait { background: var(--review-soft); color: var(--review-ink); border-radius: 12px; padding: 10px 14px; font-size: 13px; margin: 8px 0; }
.cpm-why { background: var(--bg); border: 1px dashed var(--line); color: var(--muted); border-radius: 12px; padding: 10px 14px; font-size: 13px; margin: 8px 0; }
.cpm-debug { font: 11px/1.4 monospace; background: #fefce8; color: #854d0e; border-radius: 8px; padding: 6px 10px; margin-top: 6px; }

/* Role: the drop zone, and the box of chosen files with its Submit button. */
.cpm-drop { display: block; margin: 8px 0; padding: 16px; border: 2px dashed #b8c4d8; border-radius: 14px; text-align: center;
  font-size: 13px; color: #475569; cursor: pointer; background: #fbfcfe; }
.cpm-drop:hover, .cpm-drop:focus, .cpm-drop.over { border-color: var(--brand); background: var(--review-soft); outline: none; }
.cpm-staged { background: var(--bg); border: 1px solid var(--line); border-radius: 14px; padding: 12px 14px; margin: 8px 0; }
.cpm-staged-title { font-size: 13px; font-weight: 600; margin-bottom: 8px; }
.cpm-staged-list { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; }
.cpm-chip { display: flex; align-items: center; gap: 8px; background: #fff; border: 1px solid var(--line); border-radius: 12px; padding: 6px 8px; font-size: 12px; max-width: 280px; }
.cpm-chip img, .cpm-chip-pdf { width: 46px; height: 36px; object-fit: cover; border-radius: 6px; flex: none; }
.cpm-chip-pdf { display: flex; align-items: center; justify-content: center; background: var(--idle-soft); font-weight: 700; }
.cpm-chip b { display: block; max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cpm-chip small { color: var(--muted); }
.cpm-chip button { border: 0; background: transparent; font-size: 18px; line-height: 1; color: #64748b; cursor: pointer; }
.cpm-staged-actions { display: flex; gap: 10px; }
.cpm-error { color: var(--action-ink); font-size: 13px; margin: 6px 0; }

/* Role: evidence history lines, scope, seal, file buttons and the image viewer. */
.cpm-ev { border-top: 1px solid #f1f5f9; padding: 8px 0; font-size: 13px; }
.cpm-tag { font-size: 11px; font-weight: 500; padding: 1px 8px; border-radius: 999px; background: var(--idle-soft); color: var(--idle-ink); }
.cpm-tag.st-approved { background: var(--ok-soft); color: var(--ok-ink); } .cpm-tag.st-pending { background: var(--review-soft); color: var(--review-ink); }
.cpm-tag.st-rejected { background: var(--action-soft); color: var(--action-ink); }
.cpm-seal { font-size: 11px; margin-left: 8px; color: var(--ok-ink); font-weight: 600; }
.cpm-scope { margin: 6px 0; font-size: 12px; color: var(--muted); }
.cpm-scope summary { cursor: pointer; color: var(--brand); font-weight: 600; }
.cpm-scope p { margin: 6px 0 0; }
.cpm-files { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0; }
.cpm-filebtn { border: 1px solid #cbd5e1; background: #fff; border-radius: 999px; padding: 4px 12px; font-size: 12px; cursor: pointer; max-width: 320px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cpm-filebtn:hover { border-color: var(--brand); color: var(--brand); }
.cpm-lightbox { position: fixed; inset: 0; background: rgba(11,42,91,.88); z-index: 2000; display: flex; flex-direction: column;
  align-items: center; justify-content: center; color: #fff; font-size: 13px; cursor: pointer; padding: 24px; }
.cpm-lightbox img { max-width: 92vw; max-height: 82vh; border-radius: 12px; background: #fff; margin-bottom: 10px; }

sp_widget.script:
// Role: decides which screen to show and which data it needs. The counting is done by CPMStats, the decisions by
//       CPMReview and the upload workflow by CPMEvidence, so this script only routes.
//       Everything runs inside try/catch: if something breaks, the page shows the error instead of staying silent.
(function() {
  var LIST_LIMIT = 200;    // each follow-up list shows its first 200 rows; the real total is always displayed
  var AUDIT_LIMIT = 2000;  // the audit export holds the 2000 most recent approvals
  var access, stats, review, evidence;

  data.serverBuild = '';
  data.error = '';
  data.notice = null;
  data.upload = null;
  data.file = null;
  data.audit = null;

  try {
    access = new CPMAccess();
    stats = new CPMStats();
    review = new CPMReview();
    evidence = new CPMEvidence();
    data.serverBuild = stats.VERSION;   // compared with the widget build at the bottom of the page
    route();
  } catch (e) {
    data.error = 'Unexpected error: ' + e.message + '. Look for "[CPM]" in System Log > All, and check that all Script Includes are saved in this application.';
    gs.error('[CPM] widget failed: ' + e.message);
  }

  // Role: reads the request, performs the requested action, then loads the screen to display.
  function route() {
    // --- Block 1: which page was asked for. The browser repeats these parameters on every call. ---
    var targetId = param('target');
    if (!/^[0-9a-f]{32}$/.test(targetId)) targetId = '';
    data.params = { target: targetId, debug: param('debug') };
    data.isAdmin = access.isAdmin();
    data.me = gs.getUserID();
    data.goal = new CPMUtil().intProp('green_min', 80);   // the coverage goal, drawn on the ring
    data.debug = data.params.debug == '1';                // add &debug=1 to the URL to see the raw values behind each control

    var action = input && input.action;

    // --- Block 2: light actions. They answer at once, without loading a screen. ---
    if (action == 'addFile') {
      var file = {
        name: String(input.fileName || '').replace(/[\\\/]/g, '_').substring(0, 100),
        type: String(input.contentType || '').toLowerCase()
      };
      data.upload = evidence.addFile(String(input.mapping || ''), file, String(input.content || ''), String(input.first) == 'true');
      return;
    }
    if (action == 'file') {
      data.file = evidence.getFile(String(input.evidence || ''), String(input.attachment || ''));
      return;
    }
    if (action == 'audit') {
      data.audit = access.isAdmin() ? stats.audit(AUDIT_LIMIT) : [];
      return;
    }

    // --- Block 3: actions that change something. The screen is reloaded afterwards. ---
    if (action == 'submit') data.upload = evidence.submit(String(input.mapping || ''));
    if (action == 'approve') report(review.approve(String(input.evidence || '')), 'Evidence approved: the owner has been notified.');
    if (action == 'reject') report(review.reject(String(input.evidence || ''), String(input.comment || '')), 'Evidence rejected: the owner has been notified.');

    // --- Block 4: the screen. ---
    if (targetId) loadTarget(targetId);
    else loadHome();
  }

  // Role: reads a parameter from the browser's last call, or from the address bar.
  function param(name) {
    if (input && input[name] !== undefined && input[name] !== null) return String(input[name]);
    return $sp.getParameter(name) || '';
  }

  // Role: prepares the green or red message shown at the top of the page after a review action.
  function report(error, okText) {
    data.notice = error ? { type: 'error', text: error } : { type: 'ok', text: okText };
  }

  // Role: the home screen. Everybody gets "my services" and their own follow-up lists.
  //       The compliance team also gets the whole company, the company follow-up lists and the review inbox.
  function loadHome() {
    data.screen = 'home';
    data.mine = stats.posture(access.ownedTargetIds());
    data.myFollow = stats.followUp(access.userId, LIST_LIMIT);
    if (!data.isAdmin) return;

    data.team = stats.posture(null);
    data.team.kpi.review = stats.count('x_1929776_compli_0_evidence', 'status=pending');
    data.inbox = stats.inbox(20);
    data.frameworks = stats.frameworks();
    data.follow = stats.followUp(null, LIST_LIMIT);
  }

  // Role: the page of one CI or service, after checking that the user may see it.
  function loadTarget(id) {
    data.screen = 'target';
    if (!access.canViewTarget(id)) { data.error = 'You do not have access to this page.'; return; }
    data.target = stats.detail(id);
    if (!data.target) data.error = 'Not found.';
  }
})();
